  var ta = document.querySelector("#send_textarea") || window.parent?.document?.querySelector("#send_textarea");
  if (!ta) return;

  ta.value = txt;
  ta.focus();
  ta.dispatchEvent(new Event("input", { bubbles: true, cancelable: true }));
  ta.dispatchEvent(new Event("change", { bubbles: true, cancelable: true }));

  if (window.parent && window.parent.$) {
    window.parent.$("#send_textarea").val(txt).trigger("input").trigger("change");
  }
};

window.stCopyChoice = function(btn) {
  var txt = btn.parentElement.querySelector(".st-choice-item span").textContent.trim();

  function done() {
    btn.textContent = "已复制";
    btn.classList.add("copied");
    setTimeout(function() {
      btn.textContent = "复制";
      btn.classList.remove("copied");
    }, 1200);
  }

  if (navigator.clipboard) {
    navigator.clipboard.writeText(txt).then(done).catch(function() {
      fallbackCopy(txt, done);
    });
  } else {
    fallbackCopy(txt, done);
  }
};

function fallbackCopy(txt, done) {
  var t = document.createElement("textarea");
  t.value = txt;
  t.style.position = "fixed";
  t.style.opacity = "0";
  document.body.appendChild(t);
  t.focus();
  t.select();
  document.execCommand("copy");
  document.body.removeChild(t);
  done();
}
</script>
</body>
