<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>液态紫蓝折叠组件</title>

<style>
body {
    margin: 0;
    background: transparent;
    font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial;
}

.wrapper {
    display: flex;
    justify-content: center;
    width: 100%;
    padding: 20px 0;
}

.container {
    width: 100%;
    max-width: 320px;
}

details.star-archive-light {
  margin: 20px 0;
  font-family: "Noto Serif SC", serif;
  overflow: hidden;
}

/* 标题动画 */
@keyframes gradientMove {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}

details.star-archive-light summary {
  cursor: pointer;
  padding: 14px 0;
  font-size: 20px;
  font-weight: 700;
  text-align: center;
  color: transparent;
  background-clip: text;
  -webkit-background-clip: text;
  background-image: linear-gradient(90deg, #C185FF, #6BAEFF);
  background-size: 200% 200%;
  animation: gradientMove 4s ease infinite;

  /* 手机优化 */
  -webkit-tap-highlight-color: transparent;
}

/* 内容区域 */
.neon-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.35s ease, padding 0.35s ease;
    padding: 0 12px;
    border-radius: 16px;
    background: rgba(74, 74, 102, 0.3);
    backdrop-filter: blur(22px);
    border: 1px solid rgba(230,230,250,0.25);
}

details[open] .neon-content {
    max-height: 1000px;
    padding: 12px;
}

/* 卡片 */
.option {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 6px 0;
    padding: 10px 12px;
    border-radius: 16px;
    background: rgba(74, 74, 102, 0.3);
    border: 1px solid rgba(230,230,250,0.25);
    color: #E6E6FA;
    font-size: 14px;

    /* 手机点击优化 */
    -webkit-tap-highlight-color: transparent;
}

.option:active {
    transform: scale(0.97);
}

/* 按钮（关键优化） */
.btn {
    border: none;
    padding: 6px 12px;
    border-radius: 999px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 600;
    background: rgba(74, 74, 102, 0.4);
    color: #E6E6FA;
    border: 1px solid rgba(230,230,250,0.3);

    /* ✅ 手机关键优化 */
    touch-action: manipulation;
    -webkit-user-select: none;
    user-select: none;
    -webkit-tap-highlight-color: transparent;
}

.btn:active {
    transform: scale(0.9);
}

.btn.copied {
    background: rgba(52,199,89,0.95);
    color: #fff;
}
</style>
</head>

<body>

<div class="wrapper">
  <div class="container">
    <details class="star-archive-light">
      <summary>✨剧情选项✨</summary>
      <div class="neon-content">
        <div class="option">
          <span><strong>A.</strong> <span id="textA">$1</span></span>
          <button class="btn" onclick="copyText(this, 'textA')">复制</button>
        </div>
        <div class="option">
          <span><strong>B.</strong> <span id="textB">$2</span></span>
          <button class="btn" onclick="copyText(this, 'textB')">复制</button>
        </div>
        <div class="option">
          <span><strong>C.</strong> <span id="textC">$3</span></span>
          <button class="btn" onclick="copyText(this, 'textC')">复制</button>
        </div>
        <div class="option">
          <span><strong>D.</strong> <span id="textD">$4</span></span>
          <button class="btn" onclick="copyText(this, 'textD')">复制</button>
        </div>
      </div>
    </details>
  </div>
</div>



<script>
function copyText(button, id) {
    const text = document.getElementById(id).innerText;

    // ✅ 优先现代API
    if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(() => {
            success(button);
        }).catch(() => {
            fallback(text, button);
        });
    } else {
        fallback(text, button);
    }
}

// ✅ 关键：手机兼容复制
function fallback(text, button) {
    const textarea = document.createElement("textarea");
    textarea.value = text;

    textarea.style.position = "fixed";
    textarea.style.opacity = "0";

    document.body.appendChild(textarea);
    textarea.focus();
    textarea.select();

    try {
        document.execCommand("copy");
        success(button);
    } catch (e) {
        alert("复制失败，请手动复制");
    }

    document.body.removeChild(textarea);
}

// 成功反馈
function success(button) {
    button.innerText = "✓ 已复制";
    button.classList.add("copied");

    // 📳 手机震动（增强体验）
    if (navigator.vibrate) {
        navigator.vibrate(30);
    }

    setTimeout(() => {
        button.innerText = "复制";
        button.classList.remove("copied");
    }, 1500);
}
</script>

</body>
</html>
