}

.df-private{
background:linear-gradient(145deg,#3b304c,#18131f);
border:1px solid rgba(255,255,255,.12);
}

.df-deleted{
background:linear-gradient(145deg,#5b5b63,#24242a);
opacity:.9;
}

.df-photo-body{
font-size:14px;
line-height:1.5;
font-weight:700;
}

.df-photo-meta{
margin-top:8px;
font-size:11px;
opacity:.78;
}

.df-thread-card{
overflow:hidden;
}

.df-thread-card .df-thread-head{
min-width:0;
}

.df-thread-card .df-person{
min-width:0;
width:100%;
}

.df-thread-card .df-person > div:last-child{
min-width:0;
flex:1;
overflow:hidden;
}

.df-thread-preview{
max-width:100%;
white-space:nowrap;
overflow:hidden;
text-overflow:ellipsis;
word-break:keep-all;
}

.df-call-screen{
min-height:100%;
padding:4px 0 24px;
background:#f5f4f0;
}

.df-call-screen{
min-height:100%;
padding:4px 0 86px;
background:#f5f4f0;
}

.df-call-section-title{
