font-weight:900;
margin:4px 2px 18px;
color:#1b1b1f;
}

.df-call-list{
background:#fff;
border-radius:24px;
overflow:hidden;
box-shadow:0 8px 22px rgba(0,0,0,.06);
}

.df-call-row{
display:grid;
grid-template-columns:42px minmax(0,1fr) 44px 28px;
