/* 相册：真实照片网格 */
.df-album-screen{
display:flex;
flex-direction:column;
gap:14px;
}

.df-album-head{
display:flex;
justify-content:space-between;
align-items:flex-end;
padding:0 2px 2px;
}

.df-album-title{
font-size:26px;
font-weight:900;
color:#1b1b1f;
}

.df-album-count{
font-size:12px;
color:#8b8b92;
}

.df-album-grid{
display:grid;
grid-template-columns:repeat(3,1fr);
gap:6px;
}

.df-album-tile{
position:relative;
aspect-ratio:1/1;
border-radius:14px;
overflow:hidden;
border:0;
padding:0;
cursor:pointer;
background:linear-gradient(145deg,#6f83a7,#30313c);
box-shadow:0 8px 18px rgba(0,0,0,.08);
}

.df-album-tile:nth-child(2n){
background:linear-gradient(145deg,#bd806e,#353040);
}

.df-album-tile:nth-child(3n){
background:linear-gradient(145deg,#789970,#262e35);
}

.df-album-tile:nth-child(4n){
background:linear-gradient(145deg,#8a7ac9,#2b2740);
}

.df-album-tile.private{
background:linear-gradient(145deg,#3b304c,#18131f);
}

.df-album-tile.deleted{
background:linear-gradient(145deg,#5b5b63,#24242a);
opacity:.86;
}

.df-album-tile:before{
content:attr(data-type);
position:absolute;
left:7px;
top:7px;
z-index:2;
padding:3px 7px;
border-radius:999px;
background:rgba(0,0,0,.28);
color:#fff;
font-size:10px;
font-weight:800;
backdrop-filter:blur(8px);
}

.df-album-thumb-text{
position:absolute;
left:8px;
right:8px;
bottom:8px;
z-index:2;
color:#fff;
font-size:11px;
font-weight:800;
line-height:1.35;
display:-webkit-box;
-webkit-line-clamp:3;
-webkit-box-orient:vertical;
overflow:hidden;
text-align:left;
}

.df-album-tile:after{
content:"";
position:absolute;
left:0;
right:0;
bottom:0;
height:62%;
background:linear-gradient(transparent,rgba(0,0,0,.58));
}

.df-album-private-mark,
.df-album-delete-mark{
position:absolute;
right:7px;
top:7px;
z-index:3;
width:22px;
height:22px;
border-radius:50%;
display:grid;
place-items:center;
background:rgba(0,0,0,.35);
color:#fff;
font-size:12px;
backdrop-filter:blur(8px);
}

.df-album-detail{
margin-top:4px;
border-radius:26px;
overflow:hidden;
background:#fff;
box-shadow:0 8px 22px rgba(0,0,0,.06);
color:#1b1b1f;
}

.df-album-preview{
min-height:240px;
position:relative;
display:flex;
align-items:flex-end;
padding:18px;
color:#fff;
background:linear-gradient(145deg,#6f83a7,#30313c);
}

.df-album-preview.private{
background:linear-gradient(145deg,#3b304c,#18131f);
}

.df-album-preview.deleted{
background:linear-gradient(145deg,#5b5b63,#24242a);
}

.df-album-preview:after{
content:"";
position:absolute;
left:0;
right:0;
bottom:0;
height:62%;
background:linear-gradient(transparent,rgba(0,0,0,.58));
}

.df-album-preview-text{
position:relative;
z-index:2;
font-size:15px;
font-weight:800;
line-height:1.5;
white-space:pre-wrap;
}

.df-album-info{
padding:14px 16px 16px;
}

.df-album-info-row{
display:flex;
justify-content:space-between;
gap:12px;
font-size:13px;
line-height:1.45;
padding:8px 0;
border-bottom:1px solid rgba(0,0,0,.06);
}

.df-album-info-row:last-child{
border-bottom:0;
}

.df-album-info-label{
color:#8b8b92;
white-space:nowrap;
}

.df-album-info-value{
font-weight:800;
text-align:right;
word-break:break-word;
}

.df-album-empty{
padding:30px 16px;
text-align:center;
color:#8b8b92;
background:#fff;
border-radius:24px;
}

.df-album-generate{
margin:12px 16px 16px;
width:calc(100% - 32px);
height:40px;
border:0;
border-radius:14px;
background:#111;
color:#fff;
font-size:13px;
font-weight:900;
cursor:pointer;
}

.df-album-generate:disabled{
opacity:.55;
cursor:not-allowed;
}

.df-album-preview.generated{
padding:0;
background:#111;
}

.df-album-preview.generated img{
width:100%;
height:100%;
object-fit:cover;
display:block;
}

