<script>

(function(){

const raw=document.getElementById('dfRaw').value||'';

window.dfOpenSettings=function(){

const s=dfGetNovelSettings();

document.getElementById('dfNovelEndpoint').value=s.endpoint;
document.getElementById('dfNovelStyle').value=s.style;
document.getElementById('dfNovelExtraPrompt').value=s.extraPrompt;
document.getElementById('dfNovelNegativePrompt').value=s.negativePrompt;

document.getElementById('dfSettingsModal').classList.add('active');

};

function dfHashText(text){

let h=2166136261;

const s=String(text||'');

for(let i=0;i<s.length;i++){
h^=s.charCodeAt(i);
h=Math.imul(h,16777619);
}

return (h>>>0).toString(36);

}

const dfPhoneInstanceKey=dfHashText(raw);

function dfTweetImageStorageKey(index){

const post=window.dfTweets&&window.dfTweets[index];

const tweetKey=post
?dfHashText([
post.datetime,
post.name,
post.handle,
post.content,
post.imageDesc,
post.prompt
].join('|'))
:String(index);

return `dfTweetGeneratedImage_${dfPhoneInstanceKey}_${tweetKey}`;

}

function dfGetSavedTweetImage(index){
try{
return localStorage.getItem(dfTweetImageStorageKey(index)) || '';
}catch(e){
return '';
}
}

function dfSaveTweetImage(index,imageUrl){
try{
localStorage.setItem(dfTweetImageStorageKey(index),imageUrl);
}catch(e){
console.warn('保存生成图片失败',e);
}
}

function dfRemoveTweetImage(index){
try{
localStorage.removeItem(dfTweetImageStorageKey(index));
}catch(e){}
}

window.dfOpenRawImage=function(url){
  if(!url)return;
  window.open(url,'_blank');
};

window.dfCloseSettings=function(){

document.getElementById('dfSettingsModal').classList.remove('active');

};

window.dfSaveSettings=function(){

const endpoint=document.getElementById('dfNovelEndpoint').value.trim()||'/api/novelai-generate';
const style=document.getElementById('dfNovelStyle').value.trim()||'anime';
const extraPrompt=document.getElementById('dfNovelExtraPrompt').value.trim()||'high quality, detailed, anime style';
const negativePrompt=document.getElementById('dfNovelNegativePrompt').value.trim()||'low quality, blurry, bad anatomy';

localStorage.setItem('dfNovelEndpoint',endpoint);
localStorage.setItem('dfNovelStyle',style);
localStorage.setItem('dfNovelExtraPrompt',extraPrompt);
localStorage.setItem('dfNovelNegativePrompt',negativePrompt);

if(window.DFPhoneSettings&&window.DFPhoneSettings.set){
window.DFPhoneSettings.set({
endpoint:endpoint,
style:['anime','cinematic','soft','dark','custom'].includes(style)?style:'custom',
customStyle:['anime','cinematic','soft','dark','custom'].includes(style)?'':style,
extraPrompt:extraPrompt,
negativePrompt:negativePrompt
});
}

dfCloseSettings();

};

function dfAlbumImageStorageKey(index){
const item=window.dfAlbumItems&&window.dfAlbumItems[index];

const albumKey=item
?dfHashText([
item.date,
item.type,
item.desc,
item.place,
item.flag
].join('|'))
:String(index);

return `dfAlbumGeneratedImage_${dfPhoneInstanceKey}_${albumKey}`;
}

function dfGetSavedAlbumImage(index){
try{
return localStorage.getItem(dfAlbumImageStorageKey(index)) || '';
}catch(e){
return '';
}
}

function dfSaveAlbumImage(index,imageUrl){
try{
localStorage.setItem(dfAlbumImageStorageKey(index),imageUrl);
}catch(e){
console.warn('保存相册生成图片失败',e);
}
}

function dfRemoveAlbumImage(index){
try{
localStorage.removeItem(dfAlbumImageStorageKey(index));
}catch(e){}
}

function dfCacheBustImageUrl(url){
  if(!url)return '';
  if(url.startsWith('data:'))return url;

  const joiner = url.includes('?') ? '&' : '?';
  return `${url}${joiner}df_t=${Date.now()}_${Math.random().toString(36).slice(2)}`;
}

function dfRandomSeed(){
  return Math.floor(Math.random() * 4294967295);
}



function parsePhoneHeader(){

let header='';

const withTag=raw.match(/\[PHONE\]\s*([^\n]+)/);

if(withTag){
  header=withTag[1].trim();
}else{
  header=raw
    .split('\n')
    .map(v=>v.trim())
    .filter(Boolean)[0]||'';
}

const parts=header
.split('|')
.map(v=>v.trim());

const charName=parts[0]||'未知';
const phoneTime=parts[1]||'22:47';
const battery=parts[2]||'🔋83%';
const signal=parts[3]||'5G';
const mode=parts[4]||'静音';
const screen=parts[5]||'屏幕使用 2h47m';

document.getElementById('dfClock').textContent=phoneTime;
document.getElementById('dfBattery').textContent=battery;
document.getElementById('dfSignal').textContent=signal;
document.getElementById('dfMode').textContent=mode;
document.getElementById('dfScreenUse').textContent=screen;

}

function esc(str){
return String(str||'无')
.replace(/&/g,'&amp;')
.replace(/</g,'&lt;')
.replace(/>/g,'&gt;');
}

function dfCleanPhotoDesc(text){
return String(text||'')
.replace(/^照片描述[:：]\s*/,'')
.replace(/^图片描述[:：]\s*/,'')
.trim();
}

function dfLooksLikeMetric(text){
return /^(转发|喜欢)?\s*[\d.,]+([kK万千wW])?$/.test(String(text||'').trim());
}

function dfCleanMetric(text,fallback){
const v=String(text||'').replace(/^(转发|喜欢)\s*/,'').trim();
return v || fallback;
}

function dfBuildPromptFromPhotoDesc(desc, context){
const clean=dfCleanPhotoDesc(desc);

if(!clean || clean==='无')return '无';

return [
'Generate an image from the following Chinese photo description. Translate the meaning into precise English visual details before rendering.',
`Chinese photo description: ${clean}.`,
context ? `Tweet context, also translate and use only as mood reference: ${context}.` : '',
'Use a cinematic realistic-anime style with accurate objects, coherent spatial layout, natural anatomy, and detailed lighting.',
'Preserve all concrete details from the Chinese description: subject, clothing, body posture, camera angle, environment, time of day, light color, object placement, and small incidental details.',
'If the description contains a location, keep it visible. If it contains a hand-held object, make the hand and object clearly visible.',
'Do not add text, logos, watermark, speech bubbles, UI, extra fingers, distorted hands, or unrelated characters.',
'Final image prompt should be interpreted in English visual terms.'
].filter(Boolean).join('\n');
}


function dfGetTweetPrompt(post, seed, requestId){
const basePrompt =
post.prompt && post.prompt !== '无'
? post.prompt
: dfBuildPromptFromPhotoDesc(post.imageDesc, post.content);

if(!basePrompt || basePrompt==='无')return '';

return basePrompt +
`\n\nCreate a fresh new variation. Use a different composition, camera angle, lighting, background details, and visual arrangement. Do not reuse previous image. Variation seed: ${seed}-${requestId}`;
}

function block(name){
const m=raw.match(new RegExp(`<${name}>([\\s\\S]*?)<\\/${name}>`));
return m?m[1].trim():'';
}

function splitPipe(line){
return String(line||'').split('|').map(v=>v.trim());
}

function blockRows(name){
return block(name).split('\n').map(v=>v.trim()).filter(Boolean);
}

function stripFlag(line){
let flag='';
let clean=String(line||'').trim();

if(clean.startsWith('[私密]')){
flag='私密';
clean=clean.replace(/^\[私密\]\s*/,'');
}

if(clean.startsWith('[删]')){
flag='删';
clean=clean.replace(/^\[删\]\s*/,'');
}

return {flag:flag,clean:clean};
}

function dfColorClass(v){
const s=String(v||'');
if(s.includes('🔴'))return 'red';
if(s.includes('🟢'))return 'green';
if(s.includes('🔵'))return 'blue';
if(s.includes('🟣'))return 'purple';
return 'gray';
}

const renderers={

messages:function(){

const rows=blockRows('msg');
const map=new Map();

rows.forEach(line=>{
const p=splitPipe(line);

const contact=p[0]||'未知';
const status=p[1]||'无';
const unread=parseInt(p[2]||'0',10)||0;
const time=p[3]||'';
const dir=p[4]||'←';
let content='';

if((p[5]||'').match(/^\[[^\]]+\]$/) && p.length>6){
content=(p[5]||'') + (p.slice(6).join('|')||'');
}else{
content=p.slice(5).join('|')||'';
}

if(!map.has(contact)){
map.set(contact,{
index:map.size,
contact:contact,
status:status,
unread:unread,
isGroup:contact.includes('群') || status.includes('静音'),
msgs:[]
});
}

const t=map.get(contact);
t.unread=Math.max(t.unread,unread);
t.status=status||t.status;

let sender='';
let body=content.trim();

const senderMatch=body.match(/^\[([^\]]+)\]\s*([\s\S]*)$/);
if(senderMatch){
sender=senderMatch[1].trim();
body=senderMatch[2].trim();
}

const quoted=body.match(/^"([\s\S]*)"$/);
if(quoted){
body=quoted[1];
}

let cls=dir==='→'?'df-sent':'df-received';

if(body.includes('[撤回') || body.includes('撤回了一条消息') || body.includes('已撤回')){
cls='df-recalled';
body='已撤回';
}

const bubbleInner=esc(body);

t.msgs.push({
type:'msg',
time:time,
dir:dir,
sender:sender,
body:body,
cls:cls,
text:sender?`${sender}：${body}`:body,
html:`
<div class="df-bubble ${cls}">
${sender && dir==='←'?`<div class="df-small">${esc(sender)}</div>`:''}
${bubbleInner}
<span class="df-time">${esc(time)}</span>
</div>
`
});
});

const parsedThreads=[...map.values()];
window.dfMsgThreads=parsedThreads;

const unread=parsedThreads.reduce((sum,t)=>sum+t.unread,0);

const html=parsedThreads.map(t=>{
const last=t.msgs.length?t.msgs[t.msgs.length-1].text:'无消息';

return `
<div class="df-card df-thread-card" onclick="dfOpenThread(${t.index})">
<div class="df-thread-head">
<div class="df-person">
<div class="df-avatar">${esc(t.contact.slice(0,1))}</div>
<div>
<div class="df-name">${esc(t.contact)}</div>
<div class="df-meta">${esc(t.status)} · 未读 ${t.unread}</div>
<div class="df-thread-preview">${esc(last)}</div>
</div>
</div>
${t.unread>0?`<div class="df-thread-unread">${t.unread}</div>`:''}
</div>
</div>
`;
}).join('');

document.getElementById('dfMsgBadge').textContent=unread;

return{
title:'消息',
sub:`${parsedThreads.length}个会话`,
html:html || `<div class="df-card">没有消息</div>`
};
},

notes:function(){

const items=blockRows('memo').map(line=>{
const s=stripFlag(line);
const p=splitPipe(s.clean);

return {
private:s.flag==='私密',
title:p[0]||'无标题',
time:p[1]||'无',
content:p.slice(2).join('|')||''
};
});

return{
title:'备忘录',
sub:`${items.length}条备忘`,
html:`
<div class="df-memo-screen">
${items.map(n=>`
<div class="df-memo-card ${n.private?'private':''}">
<div class="df-memo-head">
<div class="df-memo-title">
${n.private?'<span class="df-memo-lock">加密</span>':''}${esc(n.title)}
</div>
<div class="df-memo-time">${esc(n.time)}</div>
</div>
<div class="df-memo-content">${esc(n.content)}</div>
</div>
`).join('') || `<div class="df-card">没有备忘录</div>`}
</div>
`
};
},

diary:function(){

const items=blockRows('diary').map(line=>{
const p=splitPipe(line);
return {
date:p[0]||'无日期',
emoji:p[1]||'',
weather:p[2]||'',
content:p.slice(3).join('|')||''
};
});

return{
title:'日记',
sub:'私人记录',
html:`
<div class="df-diary-screen">
${items.map(d=>`
<div class="df-diary-card">
<div class="df-diary-head">
<div class="df-diary-date">${esc(d.date)}</div>
<div class="df-diary-mood">${esc(`${d.emoji} ${d.weather}`.trim())}</div>
</div>
<div class="df-diary-text ${d.content?'':'df-diary-empty'}">
${d.content?esc(d.content):'没有写。'}
</div>
</div>
`).join('') || `<div class="df-card">没有日记</div>`}
</div>
`
};
},

photos:function(){

const parsed=blockRows('album').map((line,index)=>{
const s=stripFlag(line);
const p=splitPipe(s.clean);

return {
index:index,
flag:s.flag,
date:p[0]||'',
type:p[1]||'照片',
desc:p[2]||'',
place:p[3]||'无',
prompt:p[4]||'无'
};
});

window.dfAlbumItems=parsed;

if(!parsed.length){
return{
title:'相册',
sub:'0张',
html:`<div class="df-album-empty">没有照片</div>`
};
}

const first=parsed[0];

return{
title:'相册',
sub:`${parsed.length}张`,
