function dfEscapeSlashArg(text){
return String(text||'').replace(/["\\]/g,'\\$&');
}

async function dfRunSlashCommand(cmd){

const trigger=
window.triggerSlash||
window.parent?.triggerSlash;

if(typeof trigger==='function'){
return await trigger.call(window.parent||window,cmd);
}

const st=window.SillyTavern||window.parent?.SillyTavern;

if(st&&typeof st.executeSlashCommandsWithOptions==='function'){
const result=await st.executeSlashCommandsWithOptions(cmd,{
handleExecutionErrors:true
});
return result?.pipe||result?.toString?.()||'';
}

throw new Error('找不到酒馆 /sd 命令接口，请确认这是在酒馆助手界面里运行');

}

window.dfTweetLogs = window.dfTweetLogs || {};

function dfShortError(err){
  if(!err)return '未知错误';

  const msg = err.message || String(err);

  if(msg.includes('Failed to fetch') || msg.includes('Load failed')){
    return 'Load failed：前端没有成功连到后端。检查 endpoint、Railway 是否在线、CORS、网络。';
  }

  if(msg.includes('404')){
    return '404：接口路径不存在。检查 endpoint 或 upstreamEndpoint。';
  }

  if(msg.includes('401') || msg.includes('403')){
    return '401/403：Key 无效或权限不足。检查 upstreamKey / token。';
  }

  if(msg.includes('400')){
    return '400：请求参数不匹配。检查 model、size、prompt 格式。';
  }

  if(msg.includes('500')){
    return '500：后端报错。去 Railway Logs 看详细错误。';
  }

  return msg;
}

