window.dfGenerateTweetImage=async function(index){

const post=window.dfTweets&&window.dfTweets[index];

if(!post)return;

const settings=dfGetNovelSettings();

if(!settings.endpoint){
alert('请先打开设置，填写后端代理地址 endpoint');
return;
}

const btn=(window.event&&window.event.currentTarget)||null;
const imgBox=document.getElementById('dfTweetImage'+index);

let timeout=null;

try{

const requestId = `${Date.now()}_${Math.random().toString(36).slice(2)}`;
const seed = dfRandomSeed();
const finalPrompt =
dfGetTweetPrompt(post, seed, requestId) +
(settings.characterProfiles
? `\n\nCharacter appearance references:\n${settings.characterProfiles}\nIf any named character appears in the prompt, keep their face, hairstyle, body type, clothing style, and temperament consistent with the matching reference.`
: '');


if(!finalPrompt){
alert('这条推文没有照片描述，无法生成图片');
return;
}

dfRemoveTweetImage(index);

if(btn){
btn.disabled=true;
btn.textContent='生成中...';
}

if(imgBox){
imgBox.classList.remove('generated');
imgBox.textContent='正在重新生成图片...';
}


const controller=new AbortController();

timeout=setTimeout(function(){
controller.abort();
},90000);

const res=await fetch(settings.endpoint,{
method:'POST',
headers:{
'Content-Type':'application/json'
},
signal:controller.signal,
body:JSON.stringify({
prompt:finalPrompt,
sourceLanguage:'zh-CN',
promptLanguage:'en',
translatePhotoDescription:true,

imageDescription:post.imageDesc,
tweet:post.content,

requestId:requestId,
forceRegenerate:true,
seed:seed,
niniSeed:seed,

provider:settings.provider,
upstreamEndpoint:settings.upstreamEndpoint,
upstreamKey:settings.upstreamKey,

style:settings.style,
customStyle:settings.customStyle,
model:settings.model,
token:settings.token,
extraPrompt:settings.extraPrompt,
negativePrompt:settings.negativePrompt,

niniSize:settings.niniSize,
niniSteps:settings.niniSteps,
niniScale:settings.niniScale,
niniCfg:settings.niniCfg,
niniSampler:settings.niniSampler,

openaiSize:settings.openaiSize,
openaiQuality:settings.openaiQuality,
openaiN:settings.openaiN,

character:post.name,
handle:post.handle
})
});

if(timeout){
clearTimeout(timeout);
timeout=null;
}

const data=await res.json().catch(function(){
return {};
});

if(!res.ok){
throw new Error(data.error || data.message || ('生成失败：'+res.status));
}

const imageUrl=data.imageUrl || (data.base64 ? `data:image/png;base64,${data.base64}` : '');

if(!imageUrl){
throw new Error('接口没有返回 imageUrl 或 base64');
}

const displayUrl = dfCacheBustImageUrl(imageUrl);

if(imgBox){
imgBox.classList.add('generated');
imgBox.innerHTML=`<img src="${displayUrl}" alt="tweet image" onclick="dfOpenRawImage('${imageUrl.replace(/'/g,"\\'")}')">`;

const oldBtn=document.getElementById('dfTweetFlipBtn'+index);
if(oldBtn)oldBtn.remove();

imgBox.insertAdjacentHTML('afterend',`
<button class="df-tweet-flip-btn" id="dfTweetFlipBtn${index}" data-mode="image"
onclick="
const b=this;
const next=b.dataset.mode==='image'?'desc':'image';
dfToggleGeneratedView('dfTweetImage${index}','${imageUrl.replace(/'/g,"\\'")}','${esc(post.imageDesc).replace(/'/g,"\\'")}',next);
b.dataset.mode=next;
b.textContent=next==='desc'?'查看图片':'查看描述';
">
查看描述
</button>
`);
}


dfSaveTweetImage(index,imageUrl);


if(btn){
btn.disabled=false;
btn.textContent='重新生成';
}

}catch(err){

if(timeout){
try{clearTimeout(timeout);}catch(e){}
}

const short=dfShortError(err);

dfSaveTweetLog(index,{
  stage:'fetch/generate',
  error:short,
  rawError:err && err.message ? err.message : String(err),
  endpoint:settings.endpoint,
  provider:settings.provider||'无',
  upstreamEndpoint:settings.upstreamEndpoint||'无',
  model:settings.model||'无',
  niniSize:settings.niniSize||'无',
  niniSteps:settings.niniSteps||'无',
  niniScale:settings.niniScale||'无',
  niniCfg:settings.niniCfg||'无',
  niniSampler:settings.niniSampler||'无',
  openaiSize:settings.openaiSize||'无',
  openaiQuality:settings.openaiQuality||'无',
  openaiN:settings.openaiN||'无'
});

if(imgBox){
imgBox.classList.remove('generated');

imgBox.innerHTML=`
<div class="df-tweet-error" id="dfTweetError${index}">
生成失败：${esc(err && err.message ? err.message : String(err))}
<div class="df-tweet-error-actions">
<button class="df-tweet-mini-btn" onclick="dfShowTweetLog(${index})">查看日志</button>
<button class="df-tweet-mini-btn light" onclick="dfHideTweetError(${index})">隐藏错误</button>
</div>
</div>

<div style="margin-top:10px;">
