window.dfToggleGeneratedView=function(boxId, imageUrl, desc, mode){
const box=document.getElementById(boxId);
if(!box)return;

if(mode==='desc'){
box.classList.remove('generated');
box.innerHTML=`<div class="${boxId.startsWith('dfAlbum')?'df-album-preview-text':''}">${esc(desc||'无')}</div>`;
return;
}

box.classList.add('generated');
box.innerHTML=`<img src="${dfCacheBustImageUrl(imageUrl)}" alt="generated image" onclick="dfOpenRawImage('${String(imageUrl).replace(/'/g,"\\'")}')">`;
