window.dfGenerateAlbumImage=async function(index){

const item=window.dfAlbumItems&&window.dfAlbumItems[index];
if(!item)return;

const settings=dfGetNovelSettings();
if(!settings.endpoint){
alert('请先打开设置，填写后端代理地址 endpoint');
return;
}

const btn=(window.event&&window.event.currentTarget)||null;
const imgBox=document.getElementById('dfAlbumImage'+index);

const requestId=`${Date.now()}_${Math.random().toString(36).slice(2)}`;
const seed=dfRandomSeed();

let timeout=null;

try{

dfRemoveAlbumImage(index);

if(btn){
btn.disabled=true;
btn.textContent='生成中...';
}

if(imgBox){
imgBox.classList.remove('generated');
imgBox.innerHTML=`<div class="df-album-preview-text">正在生成图片...</div>`;
}

const controller=new AbortController();

timeout=setTimeout(function(){
controller.abort();
},90000);

const albumContext=[
`Album photo type: ${item.type || 'photo'}.`,
item.place ? `Location: ${item.place}.` : '',
item.flag==='私密' ? 'Private hidden photo mood, intimate and cinematic.' : '',
item.flag==='删' ? 'Recovered deleted photo, slightly damaged memory feeling.' : ''
].filter(Boolean).join(' ');

const basePrompt =
item.prompt && item.prompt !== '无'
? item.prompt
: dfBuildPromptFromPhotoDesc(item.desc, albumContext);

const prompt =
basePrompt +
(settings.characterProfiles
? `\n\nCharacter appearance references:\n${settings.characterProfiles}\nIf any named character appears in the prompt, keep their face, hairstyle, body type, clothing style, and temperament consistent with the matching reference.`
: '') +
`\n\nCreate a fresh new variation. Use a different composition, camera angle, lighting, background details, and visual arrangement. Do not reuse previous image. Variation seed: ${seed}-${requestId}`;


const res=await fetch(settings.endpoint,{
method:'POST',
headers:{'Content-Type':'application/json'},
signal:controller.signal,
body:JSON.stringify({
prompt:prompt,
sourceLanguage:'zh-CN',
promptLanguage:'en',
translatePhotoDescription:true,

imageDescription:item.desc,
albumType:item.type,
albumDate:item.date,
albumPlace:item.place,

requestId:requestId,
forceRegenerate:true,
seed:seed,
niniSeed:seed,

provider:settings.provider,
upstreamEndpoint:settings.upstreamEndpoint,
upstreamKey:settings.upstreamKey,

style:settings.style,
customStyle:settings.customStyle,
model:settings.model,
token:settings.token,
extraPrompt:settings.extraPrompt,
negativePrompt:settings.negativePrompt,

niniSize:settings.niniSize,
niniSteps:settings.niniSteps,
niniScale:settings.niniScale,
niniCfg:settings.niniCfg,
niniSampler:settings.niniSampler,

openaiSize:settings.openaiSize,
openaiQuality:settings.openaiQuality,
openaiN:settings.openaiN
})
});

if(timeout){
clearTimeout(timeout);
timeout=null;
}

const data=await res.json().catch(function(){return {};});

if(!res.ok){
throw new Error(data.error || data.message || ('生成失败：'+res.status));
}

const imageUrl=data.imageUrl || (data.base64 ? `data:image/png;base64,${data.base64}` : '');

if(!imageUrl){
throw new Error('接口没有返回 imageUrl 或 base64');
}

const displayUrl=dfCacheBustImageUrl(imageUrl);

if(imgBox){
imgBox.classList.add('generated');
imgBox.innerHTML=`<img src="${displayUrl}" alt="album image" onclick="dfOpenRawImage('${imageUrl.replace(/'/g,"\\'")}')">`;

const oldBtn=document.getElementById('dfAlbumFlipBtn'+index);
if(oldBtn)oldBtn.remove();

imgBox.insertAdjacentHTML('afterend',`
<button class="df-flip-btn" id="dfAlbumFlipBtn${index}" data-mode="image"
onclick="
const b=this;
const next=b.dataset.mode==='image'?'desc':'image';
dfToggleGeneratedView('dfAlbumImage${index}','${imageUrl.replace(/'/g,"\\'")}','${esc(item.desc).replace(/'/g,"\\'")}',next);
b.dataset.mode=next;
b.textContent=next==='desc'?'查看图片':'查看描述';
">
查看描述
</button>
`);
}


dfSaveAlbumImage(index,imageUrl);

if(btn){
btn.disabled=false;
btn.textContent='重新生成';
}

}catch(err){

if(timeout){
try{clearTimeout(timeout);}catch(e){}
}

if(imgBox){
imgBox.classList.remove('generated');
imgBox.innerHTML=`
<div class="df-album-preview-text">
生成失败：${esc(err && err.message ? err.message : String(err))}
<br><br>
${esc(item.desc || '无')}
</div>
`;
}

if(btn){
btn.disabled=false;
btn.textContent='重新生成';
}

}
};


window.dfOpenThread=function(index){

const t=window.dfMsgThreads[index];

if(!t)return;

document.getElementById('dfAppTitle').textContent=t.contact;
document.getElementById('dfAppSub').textContent=`${t.status} · 未读 ${t.unread}`;

document.getElementById('dfContent').innerHTML=`

<div class="df-card">

<button class="df-back" onclick="dfOpen('messages')" style="padding:0 0 12px 0;">
‹ 会话列表
</button>

${t.msgs.map(m=>m.html).join('')}

</div>
`;

document.getElementById('dfContent').scrollTop=0;

};

window.dfOpen=function(id){

const data=renderers[id]();

document.getElementById('dfAppTitle').textContent=data.title;

document.getElementById('dfAppSub').textContent=data.sub;

document.getElementById('dfContent').innerHTML=data.html;

document.getElementById('dfHome')
.classList.add('hidden');

document.querySelector('.df-screen')
.classList.add('in-app');

document.getElementById('dfApp')
.classList.add('active');

document.getElementById('dfContent')
.scrollTop=0;
};

window.dfClose=function(){

document.getElementById('dfApp')
.classList.remove('active');

document.querySelector('.df-screen')
.classList.remove('in-app');

document.getElementById('dfHome')
.classList.remove('hidden');

};

function tick(){

const n=new Date();

document.getElementById('dfClock').textContent=
String(n.getHours()).padStart(2,'0')
+':'+
String(n.getMinutes()).padStart(2,'0');

}

parsePhoneHeader();

renderers.messages();

})();

</script>

